import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create glass prism
  const prismGroup = createPrism();
  group.add(prismGroup);

  // Create emissive core inside prism
  const emissiveCore = createEmissiveCore();
  prismGroup.add(emissiveCore);

  // Create caustic streak on floor
  const causticStreak = createCausticStreak();
  group.add(causticStreak);

  // Add rim light from behind-left
  const rimLight = new THREE.DirectionalLight(0xb0d0ff, 1.2);
  rimLight.position.set(-2, 1, -3);
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  // Create text
  const textGroup = createTextGroup(ctx);
  group.add(textGroup);

  // Setup handlers
  group.userData.handlers = {};
  group.userData._causticStreak = causticStreak;

  // Apply cinematic primitive for hover interaction
  if (ctx.primitives && typeof ctx.primitives['depth-rotate'] === 'function') {
    ctx.primitives['depth-rotate'](group, { maxDeg: 10 });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    gsap.killTweensOf([group.rotation, causticStreak.scale, prismGroup.rotation]);

    group.traverse((child) => {
      if (child instanceof THREE.Mesh || child instanceof THREE.Line) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };

  return group;
}

function createPrism() {
  const sideLength = 1.2;
  const prismLength = 1.8;
  const circumradius = sideLength / Math.sqrt(3);

  // Equilateral triangle vertices
  const tri = [
    [0, circumradius, 0],
    [-sideLength / 2, -circumradius / 2, 0],
    [sideLength / 2, -circumradius / 2, 0]
  ];

  const half = prismLength / 2;
  const vertices = new Float32Array([
    tri[0][0], tri[0][1], -half,
    tri[1][0], tri[1][1], -half,
    tri[2][0], tri[2][1], -half,
    tri[0][0], tri[0][1], half,
    tri[1][0], tri[1][1], half,
    tri[2][0], tri[2][1], half,
  ]);

  const indices = new Uint32Array([
    0, 2, 1, 3, 4, 5,
    0, 4, 3, 0, 1, 4,
    1, 5, 4, 1, 2, 5,
    2, 3, 5, 2, 0, 3,
  ]);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geometry.setIndex(new THREE.BufferAttribute(indices, 1));
  geometry.computeVertexNormals();

  const material = new THREE.MeshPhysicalMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    dispersion: 0.18,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color(0xe8ecf2),
    attenuationDistance: 2.5,
    color: new THREE.Color(0xffffff)
  });

  const mesh = new THREE.Mesh(geometry, material);
  const group = new THREE.Group();
  mesh.rotation.z = THREE.MathUtils.degToRad(12);
  mesh.rotation.y = THREE.MathUtils.degToRad(20);
  group.add(mesh);

  return group;
}

function createEmissiveCore() {
  const geometry = new THREE.OctahedronGeometry(0.35, 2);
  const material = new THREE.MeshStandardMaterial({
    emissive: new THREE.Color(0xff2a38),
    emissiveIntensity: 2.2,
    color: new THREE.Color(0xff2a38)
  });
  return new THREE.Mesh(geometry, material);
}

function createCausticStreak() {
  const geometry = new THREE.PlaneGeometry(2.4, 0.5);

  // Create gradient texture data programmatically
  const width = 256;
  const height = 64;
  const pixels = new Uint8Array(width * height * 4);

  for (let x = 0; x < width; x++) {
    const t = x / width;
    let r = 0, g = 0, b = 0;

    if (t < 0.2) {
      const s = t / 0.2;
      r = Math.round((1 - s) * 0x0b + s * 0xff);
      g = Math.round((1 - s) * 0x0b + s * 0x2a);
      b = Math.round((1 - s) * 0x10 + s * 0x38);
    } else if (t < 0.5) {
      const s = (t - 0.2) / 0.3;
      r = Math.round((1 - s) * 0xff + s * 0xe8);
      g = Math.round((1 - s) * 0x2a + s * 0xec);
      b = Math.round((1 - s) * 0x38 + s * 0xf2);
    } else if (t < 0.8) {
      const s = (t - 0.5) / 0.3;
      r = Math.round((1 - s) * 0xe8 + s * 0x9f);
      g = Math.round((1 - s) * 0xec + s * 0xb0);
      b = Math.round((1 - s) * 0xf2 + s * 0xc4);
    } else {
      const s = (t - 0.8) / 0.2;
      r = Math.round((1 - s) * 0x9f + s * 0x0b);
      g = Math.round((1 - s) * 0xb0 + s * 0x0b);
      b = Math.round((1 - s) * 0xc4 + s * 0x10);
    }

    for (let y = 0; y < height; y++) {
      const idx = (y * width + x) * 4;
      pixels[idx] = r;
      pixels[idx + 1] = g;
      pixels[idx + 2] = b;
      pixels[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(pixels, width, height, THREE.RGBAFormat);
  texture.needsUpdate = true;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearFilter;

  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.y = -1.1;
  mesh.rotation.x = -Math.PI / 2;

  return mesh;
}

function createTextGroup(ctx) {
  const group = new THREE.Group();

  try {
    const headlineMesh = ctx.fontAtlas.createMesh('Light, machined.', {
      fontFamily: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      color: 0xe8ecf2
    });
    headlineMesh.position.y = -1.75;
    group.add(headlineMesh);
  } catch (e) {
    console.warn('Error creating headline text:', e);
  }

  try {
    const captionMesh = ctx.fontAtlas.createMesh('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
      fontFamily: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      color: 0x9fb0c4
    });
    captionMesh.position.y = -2.25;
    group.add(captionMesh);
  } catch (e) {
    console.warn('Error creating caption text:', e);
  }

  return group;
}
